from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
import base64
import hashlib
import json

ROOT = Path('/app/auth-fixture')

def digest(value: str) -> str:
    return hashlib.sha256(value.encode()).hexdigest()

def bearer_allowed(header: str, name: str) -> bool:
    state = ROOT / f'{name}.token.sha256'
    return state.exists() and header.startswith('Bearer ') and digest(header[7:]) == state.read_text().strip()

def basic_allowed(header: str) -> bool:
    state = ROOT / 'legacy.password.sha256'
    try:
        scheme, payload = header.split(' ', 1)
        user, password = base64.b64decode(payload).decode().split(':', 1)
    except Exception:
        return False
    return scheme == 'Basic' and user == 'legacy-policy' and state.exists() and digest(password) == state.read_text().strip()

class Handler(BaseHTTPRequestHandler):
    def send_json(self, status: int, data: dict) -> None:
        body = json.dumps(data, sort_keys=True).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:
        auth = self.headers.get('Authorization', '')
        if self.path == '/release' and bearer_allowed(auth, 'release'):
            self.send_json(200, {'release': (ROOT / 'release.state').read_text().strip().split('=', 1)[1]})
        elif self.path == '/inspect' and bearer_allowed(auth, 'inspect'):
            self.send_json(200, {'service': 'release-policy', 'mode': 'read-only'})
        elif self.path == '/legacy-retention' and basic_allowed(auth):
            self.send_json(200, {'policy': (ROOT / 'retention.state').read_text().strip().split('=', 1)[1]})
        else:
            self.send_json(403, {'decision': 'deny'})

    def do_POST(self) -> None:
        auth = self.headers.get('Authorization', '')
        length = int(self.headers.get('Content-Length', '0'))
        try:
            data = json.loads(self.rfile.read(length) or b'{}')
        except json.JSONDecodeError:
            self.send_json(400, {'decision': 'invalid'})
            return
        if self.path == '/release' and bearer_allowed(auth, 'release') and isinstance(data.get('release'), str):
            (ROOT / 'release.state').write_text(f"release={data['release']}\n")
            self.send_json(200, {'release': data['release']})
        elif self.path == '/legacy-retention' and basic_allowed(auth) and isinstance(data.get('policy'), str):
            (ROOT / 'retention.state').write_text(f"policy={data['policy']}\n")
            self.send_json(200, {'policy': data['policy']})
        else:
            self.send_json(403, {'decision': 'deny'})

    def log_message(self, format: str, *args) -> None:
        return

ThreadingHTTPServer(('127.0.0.1', 18080), Handler).serve_forever()
